package weapons

import (
	"fmt"
	"github.com/MorenoLand/Moreno.HalfBricked/engine/formats"
	"math"
)

// nativeVolleyWeapon is whether the primary gun fires through nativePrimaryVolley.
func NativeVolleyWeapon(gunType string) bool {
	switch gunType {
	case "SHOTGUN", "UZI", "MINIGUN", "SNIPER", "FLAMER", "BUZZSAW", "DUALPISTOL":
		return true
	}
	return false
}

type nativeWeaponShot struct {
	Direction         uint16
	WeaponType        int
	Life, Speed, Lift float64
}
type nativeWeaponVolley struct {
	Shots        []nativeWeaponShot
	AmmoConsumed int
	LoopSound    bool
}

func NativePrimaryVolley(weapon formats.Weapon, direction uint16, rng *NativeRNG) (nativeWeaponVolley, error) {
	typeID, count, randomized, loop := 0, 1, false, false
	switch weapon.GunType {
	case "PISTOL":
	case "SHOTGUN":
		typeID, count, randomized = 1, 7, true
	case "UZI":
		typeID, randomized, loop = 2, true, true
	case "MINIGUN":
		typeID, randomized = 3, true
	case "SNIPER":
		typeID = 4
	case "FLAMER":
		typeID, randomized, loop = 5, true, true
	case "BUZZSAW":
		// Native class 6 (update 0x000a9f0c): one ammo per volley of three blades
		// fanned at facing - spread, facing and facing + spread.
		typeID, count, loop = 6, 3, true
	case "DUALPISTOL":
		// Native class 7 (fire 0x000aa174): one MULTI shot per round, alternating hands.
		typeID = 7
	default:
		return nativeWeaponVolley{}, fmt.Errorf("native primary firing unresolved for %s", weapon.GunType)
	}
	volley := nativeWeaponVolley{LoopSound: loop}
	if typeID != 0 {
		if weapon.Ammo < 1 {
			return volley, nil
		}
		volley.AmmoConsumed = 1
	}
	if randomized && rng == nil {
		return nativeWeaponVolley{}, fmt.Errorf("native weapon firing requires shared RNG")
	}
	spread := uint32(weapon.SpreadUnits)
	for i := 0; i < count; i++ {
		angle := direction
		if weapon.GunType == "BUZZSAW" {
			angle = uint16(int32(direction) + int32(i-1)*int32(weapon.SpreadUnits))
		}
		if randomized {
			angle = uint16(uint32(direction) + rng.Bounded(spread<<1) - spread)
		}
		volley.Shots = append(volley.Shots, nativeWeaponShot{Direction: angle, WeaponType: typeID, Life: weapon.Life, Speed: weapon.Speed, Lift: 20})
	}
	return volley, nil
}

func nativeWeaponDirectionRadians(direction uint16) float64 {
	return float64(float32(direction)/182) * math.Pi / 180
}

func NativeWeaponRandomFloat(rng *NativeRNG, extent float32) float32 {
	return float32(rng.Bounded(0x7ffff)) / float32(0x7ffff) * extent
}

