func NativeWeaponDirection(dx, dy float64) uint16 {
	x, y := float32(dx), float32(dy)
	if y == 0 {
		if x >= 0 {
			return 0
		}
		return 0x8000
	}
	if x == 0 {
		if y > 0 {
			return 0x4000
		}
		return 0xc000
	}
	ax, ay := x, y
	if ax < 0 {
		ax = -ax
	}
	if ay < 0 {
		ay = -ay
	}
	var angle uint16
	if ay <= ax {
		angle = nativeWeaponAtanTable[int((ay/ax)*128)]
	} else {
		angle = 0x4000 - nativeWeaponAtanTable[int((ax/ay)*128)]
	}
	if x < 0 {
		angle = 0x8000 - angle
	}
	if y < 0 {
		angle = 0 - angle
	}
	return angle
}

func nativeWeaponVelocity(direction uint16, speed float64) (float64, float64) {
	index := int(direction >> 4)
	return float64(math.Float32frombits(nativeWeaponSinBits[(index+0x400)&0xfff]) * float32(speed)), float64(math.Float32frombits(nativeWeaponSinBits[index]) * float32(speed))
}
